<script setup lang="ts">
import {computed,nextTick,onMounted,onUnmounted,ref} from 'vue'
import {asset} from '../lib/assets'
import {api,apiBaseUrl,post} from '../lib/api'
import SettingsFlow from './SettingsFlow.vue'
import MomentsFlow from './MomentsFlow.vue'
import {tr, t} from '../lib/i18n'
import ChatFlow from './ChatFlow.vue'
const props=defineProps<{token:string;person?:{id:string;peerId?:string;displayName:string;avatar?:string;status:string;following?:boolean;city?:string;age?:number;zodiac?:string;bio?:string;cards?:string[];moments?:{id:string;text:string;src:string}[]}}>()
const emit=defineEmits<{close:[];security:[];chat:[];safety:[action:'report'|'block']}>()
type Photo={id:string;src:string;position:number}
type ServerProfile={id:string;displayName:string;age:number|null;city:string|null;zodiac:string|null;bio:string;avatar:string|null;avatars:{mediaId:string;url:string;position:number}[];recentlyRemoved?:{mediaId:string;url:string;position:number}[];following:boolean;permissions:{canFollow:boolean;conversationId:string|null}}
const initial={name:'',age:'' as number|string,city:'',zodiac:'',bio:'',slots:Array(8).fill(null) as (Photo|null)[],selected:'',archive:[] as Photo[],cards:[] as string[]}
const profile=ref(initial),publicProfile=ref<ServerProfile>(),publicAvatar=ref(''),publicCards=ref<string[]>([]),publicMoments=ref<{id:string;text:string;src:string}[]>([])
const headers={Authorization:`Bearer ${props.token}`},urls:string[]=[]
onUnmounted(()=>urls.forEach(url=>URL.revokeObjectURL(url)))
async function media(url:string){const r=await fetch(apiBaseUrl+url,{headers});if(!r.ok)throw Error(`Photo unavailable (${r.status})`);const src=URL.createObjectURL(await r.blob());urls.push(src);return src}
async function apply(p:ServerProfile){const slots=Array(8).fill(null) as (Photo|null)[];for(const a of p.avatars)slots[a.position]={id:a.mediaId,src:await media(a.url),position:a.position};const archive:Photo[]=[];for(const a of p.recentlyRemoved||[])archive.push({id:a.mediaId,src:await media(a.url),position:a.position});profile.value={...initial,name:p.displayName,age:p.age??'',city:p.city??'',zodiac:p.zodiac??'',bio:p.bio,slots,archive,selected:p.avatars.find(a=>a.url===p.avatar)?.mediaId||''}}
const stats=ref({followingCount:0,followersCount:0,likesCount:0,postLikesCount:0,imageCardLikesCount:0,visits:[] as {visitorId:string;profileId:string}[],letters:[] as {content:string}[]})
const settingsOpen=ref(false),privacyOpen=ref(false)
const draft=ref({...profile.value}),view=ref(props.person?'public':'profile'),sheet=ref(''),error=ref(''),notice=ref(''),kind=ref('Following'),outgoing=ref(false),remove=ref(-1),zoom=ref(1),canvas=ref<HTMLCanvasElement>(),file=ref<HTMLInputElement>(),image=ref<HTMLImageElement>(),followed=ref(!!props.person?.following),busy=ref(false),largePhoto=ref('')
const own=computed(()=>profile.value.slots.find(p=>p?.id===profile.value.selected)?.src||asset('05-avatars/avatar-placeholder'))
const photo=computed(()=>publicAvatar.value||asset('05-avatars/avatar-placeholder'))
type Connection={id:string;peerId?:string;displayName:string;avatar?:string;status:string;following?:boolean}
const followers=ref<Connection[]>([]),connections=ref<Connection[]>([]),letters=ref<string[]>([]),selectedPerson=ref<Connection>(),selectedChat=ref<Connection>(),loading=ref(false)
const following=computed(()=>connections.value.filter(c=>c.following))
const visits=ref<Connection[]>([]),incoming=ref<Connection[]>([])
async function load(){loading.value=true;try{if(props.person){const p=await api<ServerProfile>(`/profiles/${props.person.peerId||props.person.id}`,{headers});publicProfile.value=p;publicAvatar.value=p.avatar?await media(p.avatar):'';followed.value=p.following;const cards=await api<{items:{url:string}[]}>(`/profiles/${p.id}/image-cards`,{headers});publicCards.value=await Promise.all(cards.items.map(c=>media(c.url)));const posts=await api<{items:{id:string;content:string;attachments:{url:string;kind:string}[]}[]}>(`/posts?userId=${p.id}&limit=100&offset=0`,{headers});publicMoments.value=await Promise.all(posts.items.map(async m=>({id:m.id,text:m.content,src:m.attachments.find(a=>a.kind==='image')?await media(m.attachments.find(a=>a.kind==='image')!.url):''})));return}const p=await api<ServerProfile>('/profiles/me',{headers});await apply(p);stats.value=await api('/profiles/me/stats',{headers});letters.value=stats.value.letters.map(l=>l.content);const all:Connection[]=[];for(let offset=0;;offset+=100){const r=await api<{items:Connection[];hasMore?:boolean}>(`/conversations?tab=messages&hidden=false&limit=100&offset=${offset}`,{headers});all.push(...r.items);if(!r.hasMore)break}connections.value=all;const fans:Connection[]=[];for(let offset=0;;offset+=100){const r=await api<{items:{id:string;displayName:string}[]}>(`/profiles/me/followers?limit=100&offset=${offset}`,{headers});fans.push(...r.items.map(f=>{const c=all.find(c=>c.peerId===f.id);return {id:c?.id||f.id,peerId:f.id,displayName:f.displayName,status:c?.status||'waiting'}}));if(r.items.length<100)break}followers.value=fans;visits.value=[];incoming.value=[];for(const v of stats.value.visits){const id=v.visitorId===p.id?v.profileId:v.visitorId;const other=await api<Pick<ServerProfile,'id'|'displayName'>>(`/profiles/${id}/summary`,{headers});const connection=all.find(c=>c.peerId===other.id);const c={id:connection?.id||other.id,peerId:other.id,displayName:other.displayName,status:connection?.status||'waiting'};(v.visitorId===p.id?visits.value:incoming.value).push(c)}}catch(e){error.value=(e as Error).message}finally{loading.value=false}}
onMounted(()=>void load())
const title=computed(()=>view.value==='edit'?'Edit profile':view.value==='public'?'Profile':view.value==='connections'?kind.value:view.value==='visitors'?'Visitors':view.value==='letters'?'My letters':'My little corner')
function back(){error.value='';if(sheet.value){sheet.value=['archive','remove','crop'].includes(sheet.value)?'gallery':'';return}if(['profile','public'].includes(view.value))emit('close');else view.value='profile'}
function edit(){draft.value={...profile.value};view.value='edit';error.value=''}
async function save(){const age=Number(draft.value.age);if(!draft.value.name.trim()||!Number.isInteger(age)||age<18||age>100){error.value='Enter a name and an age between 18 and 100.';return}busy.value=true;error.value='';try{await apply(await api<ServerProfile>('/profiles/me',{method:'PATCH',headers:{...headers,'Content-Type':'application/json'},body:JSON.stringify({displayName:draft.value.name.trim(),age,city:draft.value.city.trim(),...(draft.value.zodiac?{zodiac:draft.value.zodiac}:{}),bio:draft.value.bio})}));view.value='profile';notice.value='Profile saved.'}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function avatarAction(action:string,mediaId:string){busy.value=true;error.value='';try{await apply(await post<ServerProfile>('/profiles/me/avatars',{action,mediaId,...(action==='remove'?{confirm:true}:{})},props.token));sheet.value=action==='select'?'':'gallery'}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
function removePhoto(){void avatarAction('remove',profile.value.slots[remove.value]!.id)}
function restore(i:number){void avatarAction('restore',profile.value.archive[i]!.id)}
function pick(){file.value!.value='';file.value!.click()}
async function upload(e:Event){const f=(e.target as HTMLInputElement).files?.[0];if(!f)return;const img=new Image();const url=URL.createObjectURL(f);img.onload=async()=>{image.value=img;zoom.value=1;sheet.value='crop';await nextTick();draw();URL.revokeObjectURL(url)};img.onerror=()=>{error.value='This photo could not be opened.';URL.revokeObjectURL(url)};img.src=url}
function draw(){const c=canvas.value!,img=image.value!,scale=Math.max(c.width/img.width,c.height/img.height)*zoom.value;c.getContext('2d')!.drawImage(img,(c.width-img.width*scale)/2,(c.height-img.height*scale)/2,img.width*scale,img.height*scale)}
async function saveAvatar(){busy.value=true;error.value='';try{const blob=await new Promise<Blob>(resolve=>canvas.value!.toBlob(b=>resolve(b!),'image/jpeg',.85));const uploaded=await api<{id:string}>('/media/uploads?purpose=avatar&filename=avatar.jpg',{method:'POST',headers:{...headers,'Content-Type':'image/jpeg'},body:blob});await post('/profiles/me/avatars',{action:'add',mediaId:uploaded.id},props.token);await apply(await post<ServerProfile>('/profiles/me/avatars',{action:'select',mediaId:uploaded.id},props.token));sheet.value='';notice.value='Avatar saved.'}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function follow(){if(!props.person||(!publicProfile.value?.permissions.canFollow||props.person.status!=='open')||busy.value)return;busy.value=true;error.value='';try{await api(`/conversations/${props.person.id}`,{method:'PATCH',headers:{Authorization:`Bearer ${props.token}`,'Content-Type':'application/json'},body:JSON.stringify({following:!followed.value})});followed.value=!followed.value}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
</script>
<template>
<SettingsFlow @security="emit('security')" :token="token" :privacy="privacyOpen" v-if="settingsOpen" @close="settingsOpen=false" />
<ProfileFlow v-if="selectedPerson" :token="token" :person="selectedPerson" @close="selectedPerson=undefined;load()" @chat="selectedChat=selectedPerson;selectedPerson=undefined" @safety="selectedChat=selectedPerson;selectedPerson=undefined" />
<ChatFlow v-if="selectedChat" :token="token" :conversation="selectedChat" @close="selectedChat=undefined;load()" @collect="selectedChat=undefined;notice='Collect your reply from Messages to continue.'" />
<section v-show="!selectedPerson&&!selectedChat" class="d4-profile" @keydown.esc="back">
<header><button id="page-back" :aria-label="tr('Back')" @click="back">‹</button><h1>{{tr(title)}}</h1><button v-if="person" id="public-more" :aria-label="tr('Profile options')" @click="sheet='safety'">•••</button><button v-else id="open-settings" :aria-label="t('settings')" @click="privacyOpen=false;settingsOpen=true"><img :src="asset('08-interface-icons/icon-settings-light-24')" width="24" height="24" alt=""></button></header>
<p v-if="error" role="alert" class="d4-error">{{tr(error)}}</p><p v-if="notice" role="status" class="d4-note">{{tr(notice)}}</p>
<div class="d4-body" :key="view">
<template v-if="view==='profile'"><div class="profile-hero"><button id="edit-avatar" :aria-label="tr('Change avatar')" @click="sheet='gallery'"><img :src="own" :alt="tr('Your avatar')"><span>▣</span></button><button id="edit-profile" @click="edit"><strong>{{profile.name}}</strong></button><p>{{profile.age}} · {{profile.zodiac?profile.zodiac+' · ':''}}{{profile.city}}</p><p>{{profile.bio}}</p></div><div class="profile-counters"><button id="following" @click="kind='Following';view='connections'">{{stats.followingCount}}<small>{{tr("Following")}}</small></button><button id="followers" @click="kind='Followers';view='connections'">{{stats.followersCount}}<small>{{tr("Followers")}}</small></button><button id="likes" @click="sheet='likes'">{{stats.likesCount}}<small>{{tr("Likes")}}</small></button><button id="profile-visitors" @click="view='visitors'">◷<small>{{tr("Visitors ›")}}</small></button></div><button id="profile-global-visibility" class="d4-row" @click="privacyOpen=true;settingsOpen=true">{{tr('Profile visibility')}} <span>›</span></button><MomentsFlow :token="token" /><button id="profile-letters" class="d4-row" @click="view='letters'">{{tr("My letters")}} <span>›</span></button></template>
<template v-else-if="view==='edit'"><form @submit.prevent="save" novalidate><label>{{tr("Nickname")}}<input id="edit-name" v-model="draft.name" maxlength="24"></label><label>{{tr("Age")}}<input id="edit-age" v-model="draft.age" type="number" min="18" max="100" :aria-invalid="!!error"></label><label>{{tr("City")}}<input id="edit-city" v-model="draft.city" maxlength="40"></label><label>{{tr("Zodiac")}}<select id="edit-zodiac" v-model="draft.zodiac"><option value="" disabled>—</option><option v-for="sign in ['Aries','Taurus','Gemini','Cancer','Leo','Virgo','Libra','Scorpio','Sagittarius','Capricorn','Aquarius','Pisces']" :key="sign" :value="sign">{{tr(sign)}}</option></select></label><label>{{tr("About me")}}<textarea id="edit-bio" v-model="draft.bio" maxlength="200"></textarea></label><button id="change-avatar" type="button" class="d4-row" @click="sheet='gallery'">{{tr("Change avatar")}}</button><button id="save-profile" :disabled="busy||loading" class="primary">{{tr("Save changes")}}</button></form></template>
<template v-else-if="view==='public'"><div class="profile-hero"><button id="public-avatar" :aria-label="tr('View profile photo')" @click="largePhoto=photo;sheet='photo'"><img :src="photo" :alt="publicProfile?.displayName"></button><h2>{{publicProfile?.displayName}}</h2><p>{{[publicProfile?.age,publicProfile?.zodiac,publicProfile?.city].filter(Boolean).join(' · ')}}</p><p>{{publicProfile?.bio}}</p></div><div class="d4-cards"><button v-for="src in publicCards" :key="src" @click="largePhoto=src;sheet='photo'"><img :src="src" :alt="tr('Image card')"></button></div><h2>{{tr("Moments")}}</h2><article v-for="m in publicMoments" :key="m.id" class="d4-moment"><p>{{m.text}}</p><button v-if="m.src" @click="largePhoto=m.src;sheet='photo'"><img :src="m.src" :alt="tr('Moment photo')"></button></article><p v-if="!publicMoments.length" class="d4-empty">{{tr("No moments yet.")}}</p><div class="d4-public-actions"><p v-if="person!.status!=='open'">{{tr("Following unlocks after they reply.")}}</p><button id="public-follow" class="d4-row" :disabled="!publicProfile?.permissions.canFollow||person!.status!=='open'||busy" @click="follow">{{tr(followed?'✓ Following':'＋ Follow')}}</button><button id="public-chat" class="primary" @click="emit('chat')">{{tr("Chat")}}</button></div></template>
<template v-else-if="view==='connections'"><button v-for="c in kind==='Following'?following:followers" :key="c.id" class="d4-row" :data-connection="c.id" @click="selectedPerson=c">{{c.displayName}} <span>›</span></button><p v-if="kind==='Followers'?!followers.length:!following.length" class="d4-empty">{{tr(kind==='Following'?'No following yet.':'No followers yet.')}}</p></template>
<template v-else-if="view==='visitors'"><div class="d4-tabs"><button :aria-pressed="!outgoing" @click="outgoing=false">{{tr("Visited me")}}</button><button :aria-pressed="outgoing" @click="outgoing=true">{{tr("I visited")}}</button></div><button v-for="c in outgoing?visits:incoming" :key="c.id" class="d4-row" @click="selectedPerson=c">{{c.displayName}} <span>›</span></button><p v-if="!(outgoing?visits:incoming).length" class="d4-empty">{{tr(outgoing?'No visits yet.':'No visitors yet.')}}</p></template>
<template v-else><p v-if="loading">{{tr("Loading letters…")}}</p><p v-else-if="!letters.length" class="d4-empty">{{tr("No letters yet.")}}</p><article v-for="(letter,i) in letters" :key="i" class="d4-moment">{{letter}}</article></template>
</div>
<input ref="file" type="file" accept="image/*" style="display:none" @change="upload">
<Transition name="d4-sheet"><div v-if="sheet" class="d4-veil" @click.self="back"><section role="dialog" aria-modal="true" :aria-label="tr(sheet==='gallery'?'Avatar':sheet==='archive'?'Recently removed':sheet==='remove'?'Remove photo':sheet==='crop'?'Crop avatar':sheet==='photo'?'Profile photo':sheet==='likes'?'Likes':'Report or block')" class="d4-sheet"><button class="d4-close" :aria-label="tr('Close')" @click="back">×</button>
<template v-if="sheet==='gallery'"><h2>{{tr("Choose an avatar")}}</h2><div class="avatar-gallery"><div v-for="(p,i) in profile.slots" :key="i" class="avatar-slot"><template v-if="p"><button class="avatar-option" :data-avatar-slot="i" :aria-pressed="profile.selected===p.id" @click="avatarAction('select',p.id)"><img :src="p.src" :alt="tr(`Avatar ${i+1}`)"><span v-if="profile.selected===p.id">✓</span></button><button class="avatar-remove" :data-remove-avatar="i" :aria-label="tr(`Remove photo ${i+1}`)" @click="remove=i;sheet='remove'">×</button></template><button v-else class="avatar-empty" :data-upload-avatar="i" :aria-label="tr(`Upload a photo ${i+1}`)" @click="pick()">▣<small>{{tr("Not uploaded")}}</small></button></div></div><button id="upload-avatar" class="primary" :disabled="profile.slots.every(Boolean)" @click="pick()">{{tr("Upload a photo")}}</button><button v-if="profile.archive.length" id="removed-avatars" class="d4-row" @click="sheet='archive'">{{tr("Recently removed (")}}{{profile.archive.length}})</button></template>
<template v-else-if="sheet==='remove'"><h2>{{tr("Remove this photo?")}}</h2><p>{{tr("You can restore removed photos from Recently removed.")}}</p><button id="confirm-remove-avatar" class="primary" @click="removePhoto">{{tr("Remove photo")}}</button><button class="d4-row" @click="sheet='gallery'">{{tr("Cancel")}}</button></template>
<template v-else-if="sheet==='archive'"><h2>{{tr("Recently removed")}}</h2><p>{{tr("Restore a photo to an empty position.")}}</p><div class="avatar-gallery"><button v-for="(p,i) in profile.archive" :key="p.id" class="avatar-option" :data-restore-avatar="i" :aria-label="tr(`Restore ${i+1}`)" @click="restore(i)"><img :src="p.src" :alt="tr('Removed avatar')"></button></div><button id="avatar-gallery-back" class="d4-row" @click="sheet='gallery'">{{tr("Back")}}</button></template>
<template v-else-if="sheet==='crop'"><h2>{{tr("Crop avatar")}}</h2><canvas id="avatar-canvas" ref="canvas" width="320" height="320"></canvas><label>{{tr("Zoom")}}<input id="avatar-zoom" v-model="zoom" type="range" min="1" max="3" step=".01" @input="draw"></label><button id="save-avatar" :disabled="busy" class="primary" @click="saveAvatar">{{tr("Use photo")}}</button></template>
<template v-else-if="sheet==='photo'"><img class="d4-photo" :src="largePhoto" :alt="tr('Profile photo')"></template>
<template v-else-if="sheet==='likes'"><h2>{{tr("Likes")}}</h2><p>{{tr("Likes")}} <strong>{{stats.likesCount}}</strong></p><p data-likes="posts">{{tr("Moments")}} <strong>{{stats.postLikesCount}}</strong></p><p data-likes="cards">{{tr("Image cards")}} <strong>{{stats.imageCardLikesCount}}</strong></p><button class="primary" @click="sheet=''">{{tr("Got it")}}</button></template>
<template v-else-if="sheet==='safety'"><h2>{{tr("Keep your little corner safe")}}</h2><button id="safety-report" class="d4-row" @click="emit('safety','report')">{{tr("Report")}}</button><button id="safety-block" class="d4-row" @click="emit('safety','block')">{{tr("Block")}}</button></template>
</section></div></Transition>
</section>
</template>
<style scoped>
.d4-profile{position:absolute;inset:0;z-index:30;background:#0d1713;color:#e4efd9;display:flex;flex-direction:column;padding-top:48px}.d4-profile header{display:flex;align-items:center;justify-content:space-between;padding:0 20px;height:56px;flex-shrink:0}.d4-profile header button{background:none;border:0;color:#b8ccb0;font-size:26px}.d4-profile h1{font-size:19px;font-weight:500}.d4-profile h2{font-size:17px;font-weight:500}.d4-body{overflow:auto;padding:12px 24px 40px;flex:1;animation:d4-open .3s ease-out}.d4-profile button{cursor:pointer}.d4-profile button:disabled{opacity:.4;cursor:default}.profile-hero{text-align:center;padding:20px 0}.profile-hero button{display:block;margin:auto;background:none;border:0;color:inherit;position:relative}.profile-hero img{width:88px;height:88px;object-fit:cover;border-radius:50%;border:2px solid #b5fa7055}.profile-hero span{position:absolute;right:4px;bottom:0;border-radius:50%;background:#b5fa70;color:#183020;padding:5px}.profile-hero strong{display:inline-block;font-size:18px;font-weight:500;margin-top:14px}.profile-hero p{font-size:12px;color:#a2b797;line-height:1.8}.profile-counters{display:flex;justify-content:space-between;border-bottom:1px solid #c8e4b31a;padding:10px 0 26px}.profile-counters button{border:0;background:none;color:#d0e2c4;font-size:20px}.profile-counters small{display:block;font-size:11px;margin-top:5px;color:#a2b797}.d4-moment{padding:16px;background:#233729;border-radius:14px;margin:12px 0}.d4-moment button,.d4-cards button{padding:0;background:none;border:0}.d4-moment img{width:100%;border-radius:12px}.d4-cards img{width:136px;height:180px;object-fit:cover;border-radius:14px}.d4-cards{gap:12px;overflow:auto;min-height:140px;display:flex;align-items:center;color:#81947a;font-size:13px}.d4-note{font-size:11px;color:#81947a;line-height:1.8;padding:0 16px}.d4-error{color:#edb39f;font-size:13px;padding:0 24px}.d4-row{display:block;width:100%;text-align:left;border:0;border-bottom:1px solid #b8ccb015;padding:1